[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Climate Change 2023 - IPCC AR6 Synthesis Report Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: #060e1a;
    color: #f1f5f9;
    width: 1200px;
    height: 1697px;
    overflow: hidden;
  }

  .poster {
    width: 1200px;
    height: 1697px;
    background: linear-gradient(175deg, #0a1628 0%, #0f1d32 40%, #0a1628 100%);
    padding: 48px 56px 36px;
    display: flex;
    flex-direction: column;
    gap: 28px;
    position: relative;
  }

  .poster::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 6px;
    background: linear-gradient(90deg, #06b6d4, #f59e0b, #ef4444, #dc2626);
  }

  /* ── HEADER ── */
  .header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    border-bottom: 1px solid rgba(255,255,255,0.08);
    padding-bottom: 20px;
  }

  .header-left { max-width: 820px; }

  .header-tag {
    display: inline-block;
    background: rgba(6,182,212,0.15);
    color: #22d3ee;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 3px;
    margin-bottom: 12px;
  }

  .header h1 {
    font-size: 36px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.5px;
    color: #f8fafc;
  }

  .header h1 span {
    background: linear-gradient(90deg, #f59e0b, #ef4444);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .header-sub {
    font-size: 14px;
    color: #94a3b8;
    margin-top: 8px;
    line-height: 1.5;
    max-width: 700px;
  }

  .header-right {
    text-align: right;
    font-size: 11px;
    color: #64748b;
    line-height: 1.6;
  }

  .header-right strong {
    color: #94a3b8;
    font-weight: 600;
  }

  /* ── METRICS CENTERPIECE ── */
  .metrics-section {
    background: linear-gradient(135deg, rgba(15,29,50,0.8), rgba(10,22,40,0.9));
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 12px;
    padding: 28px 32px 24px;
  }

  .metrics-label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #64748b;
    margin-bottom: 18px;
  }

  .metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }

  .metric-card {
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 8px;
    padding: 20px 18px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .metric-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }

  .metric-card.warm-1::before { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
  .metric-card.warm-2::before { background: linear-gradient(90deg, #f97316, #fb923c); }
  .metric-card.warm-3::before { background: linear-gradient(90deg, #ef4444, #f87171); }
  .metric-card.warm-4::before { background: linear-gradient(90deg, #dc2626, #ef4444); }
  .metric-card.cool-1::before { background: linear-gradient(90deg, #06b6d4, #22d3ee); }
  .metric-card.cool-2::before { background: linear-gradient(90deg, #0ea5e9, #38bdf8); }

  .metric-value {
    font-size: 38px;
    font-weight: 900;
    line-height: 1.1;
    margin-bottom: 6px;
  }

  .metric-card.warm-1 .metric-value { color: #fbbf24; }
  .metric-card.warm-2 .metric-value { color: #fb923c; }
  .metric-card.warm-3 .metric-value { color: #f87171; }
  .metric-card.warm-4 .metric-value { color: #ef4444; }
  .metric-card.cool-1 .metric-value { color: #22d3ee; }
  .metric-card.cool-2 .metric-value { color: #38bdf8; }
  .metric-card.highlight .metric-value {
    color: #fbbf24;
    text-shadow: 0 0 30px rgba(251,191,36,0.3);
  }

  .metric-unit {
    font-size: 16px;
    font-weight: 400;
    opacity: 0.7;
  }

  .metric-label {
    font-size: 11px;
    color: #94a3b8;
    line-height: 1.4;
    margin-top: 4px;
  }

  .metric-detail {
    font-size: 9px;
    color: #64748b;
    margin-top: 3px;
    line-height: 1.3;
  }

  .metrics-row-2 {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 16px;
  }

  .metric-card.large {
    padding: 24px 20px;
  }

  .metric-card.large .metric-value {
    font-size: 44px;
  }

  /* ── MAIN CONTENT GRID ── */
  .content-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    flex: 1;
    min-height: 0;
  }

  .section-card {
    background: rgba(15,29,50,0.5);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 10px;
    padding: 24px;
    display: flex;
    flex-direction: column;
  }

  .section-card.full-width {
    grid-column: 1 / -1;
  }

  .section-number {
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    color: #64748b;
    letter-spacing: 1px;
    margin-bottom: 6px;
  }

  .section-title {
    font-size: 17px;
    font-weight: 700;
    color: #e2e8f0;
    margin-bottom: 4px;
  }

  .section-desc {
    font-size: 11.5px;
    color: #94a3b8;
    line-height: 1.5;
    margin-bottom: 16px;
  }

  .infographic-container {
    flex: 1;
    min-height: 200px;
    border-radius: 6px;
    overflow: hidden;
  }

  /* ── SSP TABLE ── */
  .ssp-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
  }

  .ssp-table th {
    text-align: left;
    padding: 8px 10px;
    font-weight: 600;
    color: #94a3b8;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .ssp-table td {
    padding: 9px 10px;
    border-bottom: 1px solid rgba(255,255,255,0.04);
    color: #cbd5e1;
  }

  .ssp-table tr:last-child td { border-bottom: none; }

  .ssp-bar-cell {
    width: 40%;
  }

  .ssp-bar-wrap {
    background: rgba(255,255,255,0.05);
    border-radius: 3px;
    height: 18px;
    overflow: hidden;
    position: relative;
  }

  .ssp-bar {
    height: 100%;
    border-radius: 3px;
    display: flex;
    align-items: center;
    padding-left: 8px;
    font-size: 10px;
    font-weight: 600;
    color: #fff;
    min-width: 40px;
  }

  .temp-value {
    font-weight: 700;
    font-size: 13px;
    min-width: 50px;
  }

  /* ── RISK ITEMS ── */
  .risk-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .risk-item {
    display: flex;
    gap: 14px;
    align-items: flex-start;
    padding: 14px 16px;
    background: rgba(255,255,255,0.03);
    border-left: 3px solid;
    border-radius: 0 6px 6px 0;
  }

  .risk-item.food { border-left-color: #f59e0b; }
  .risk-item.water { border-left-color: #06b6d4; }
  .risk-item.health { border-left-color: #ef4444; }

  .risk-icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    flex-shrink: 0;
  }

  .risk-item.food .risk-icon { background: rgba(245,158,11,0.15); }
  .risk-item.water .risk-icon { background: rgba(6,182,212,0.15); }
  .risk-item.health .risk-icon { background: rgba(239,68,68,0.15); }

  .risk-content { flex: 1; }

  .risk-label {
    font-size: 13px;
    font-weight: 700;
    color: #e2e8f0;
    margin-bottom: 3px;
  }

  .risk-desc {
    font-size: 11px;
    color: #94a3b8;
    line-height: 1.45;
  }

  /* ── COMPARISON ── */
  .compare-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }

  .compare-col {
    padding: 18px;
    border-radius: 8px;
    border: 1px solid rgba(255,255,255,0.06);
  }

  .compare-col.cool {
    background: rgba(6,182,212,0.06);
    border-color: rgba(6,182,212,0.15);
  }

  .compare-col.warm {
    background: rgba(245,158,11,0.06);
    border-color: rgba(245,158,11,0.15);
  }

  .compare-col-title {
    font-size: 15px;
    font-weight: 800;
    margin-bottom: 14px;
    text-align: center;
  }

  .compare-col.cool .compare-col-title { color: #22d3ee; }
  .compare-col.warm .compare-col-title { color: #fbbf24; }

  .compare-item {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 8px 0;
    border-bottom: 1px solid rgba(255,255,255,0.04);
  }

  .compare-item:last-child { border-bottom: none; }

  .compare-item-label {
    font-size: 11px;
    color: #94a3b8;
  }

  .compare-item-value {
    font-size: 14px;
    font-weight: 700;
  }

  .compare-col.cool .compare-item-value { color: #22d3ee; }
  .compare-col.warm .compare-item-value { color: #fbbf24; }

  .compare-item-desc {
    font-size: 9px;
    color: #64748b;
    display: block;
    text-align: right;
  }

  /* ── URGENCY SECTION ── */
  .urgency-section {
    background: linear-gradient(135deg, rgba(220,38,38,0.08), rgba(245,158,11,0.06));
    border: 1px solid rgba(239,68,68,0.15);
    border-radius: 10px;
    padding: 28px 32px;
    display: flex;
    gap: 32px;
    align-items: center;
  }

  .urgency-left {
    flex: 1;
  }

  .urgency-left .section-title {
    color: #fbbf24;
    font-size: 20px;
  }

  .urgency-text {
    font-size: 12.5px;
    color: #cbd5e1;
    line-height: 1.6;
    margin-top: 10px;
  }

  .urgency-text strong {
    color: #fbbf24;
    font-weight: 700;
  }

  .urgency-right {
    width: 420px;
    flex-shrink: 0;
  }

  /* ── STEPS ── */
  .steps-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .step-item {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 10px 16px;
    background: rgba(255,255,255,0.03);
    border-radius: 6px;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .step-num {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 800;
    flex-shrink: 0;
  }

  .step-item:nth-child(1) .step-num { background: rgba(251,191,36,0.2); color: #fbbf24; }
  .step-item:nth-child(2) .step-num { background: rgba(249,115,22,0.2); color: #fb923c; }
  .step-item:nth-child(3) .step-num { background: rgba(239,68,68,0.2); color: #f87171; }
  .step-item:nth-child(4) .step-num { background: rgba(220,38,38,0.2); color: #ef4444; }
  .step-item:nth-child(5) .step-num { background: rgba(6,182,212,0.2); color: #22d3ee; }

  .step-text {
    font-size: 12px;
    color: #e2e8f0;
    font-weight: 500;
  }

  /* ── OBSERVED CHANGES DETAIL ── */
  .obs-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .obs-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    background: rgba(255,255,255,0.03);
    border-radius: 6px;
    border: 1px solid rgba(255,255,255,0.04);
  }

  .obs-value {
    font-size: 18px;
    font-weight: 800;
    color: #fbbf24;
    min-width: 70px;
  }

  .obs-label {
    font-size: 10.5px;
    color: #94a3b8;
    line-height: 1.4;
  }

  .obs-item .obs-icon {
    font-size: 16px;
    width: 32px;
    text-align: center;
    flex-shrink: 0;
  }

  /* ── FOOTER ── */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 9.5px;
    color: #475569;
    border-top: 1px solid rgba(255,255,255,0.06);
    padding-top: 12px;
  }

  .footer-source {
    font-style: italic;
  }

  /* ── POPULATION CALLOUT ── */
  .population-callout {
    text-align: center;
    padding: 16px;
    background: linear-gradient(135deg, rgba(239,68,68,0.1), rgba(220,38,38,0.05));
    border: 1px solid rgba(239,68,68,0.15);
    border-radius: 8px;
    margin-top: 12px;
  }

  .population-callout .value {
    font-size: 28px;
    font-weight: 900;
    color: #f87171;
    line-height: 1.2;
  }

  .population-callout .label {
    font-size: 11px;
    color: #fca5a5;
    margin-top: 2px;
  }

  /* ── SEA LEVEL DETAIL ── */
  .sea-level-row {
    display: flex;
    gap: 16px;
    margin-top: 12px;
  }

  .sea-level-card {
    flex: 1;
    padding: 12px;
    background: rgba(6,182,212,0.06);
    border: 1px solid rgba(6,182,212,0.12);
    border-radius: 6px;
    text-align: center;
  }

  .sea-level-card .value {
    font-size: 16px;
    font-weight: 700;
    color: #22d3ee;
  }

  .sea-level-card .label {
    font-size: 9.5px;
    color: #67e8f9;
    margin-top: 2px;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- ── HEADER ── -->
  <div class="header">
    <div class="header-left">
      <div class="header-tag">IPCC Sixth Assessment Report &mdash; Synthesis 2023</div>
      <h1>Climate Change 2023:<br><span>Key Findings from the AR6 Synthesis Report</span></h1>
      <p class="header-sub">The most comprehensive scientific assessment of climate change to date. Human-caused warming is already affecting every region on Earth, with widespread and intensifying consequences. The choices made in this decade will determine our future.</p>
    </div>
    <div class="header-right">
      <strong>Intergovernmental Panel</strong><br>on Climate Change<br><br>
      Published March 2023<br>
      AR6 Synthesis Report
    </div>
  </div>

  <!-- ── SEVEN HEADLINE METRICS ── -->
  <div class="metrics-section">
    <div class="metrics-label">Headline Indicators</div>
    <div class="metrics-grid">
      <div class="metric-card warm-1">
        <div class="metric-value">1.1<span class="metric-unit">°C</span></div>
        <div class="metric-label">Surface temperature rise</div>
        <div class="metric-detail">2011–2020 vs. 1850–1900</div>
      </div>
      <div class="metric-card warm-2">
        <div class="metric-value">410<span class="metric-unit"> ppm</span></div>
        <div class="metric-label">CO₂ concentration (2019)</div>
        <div class="metric-detail">Highest in 2 million years</div>
      </div>
      <div class="metric-card warm-3">
        <div class="metric-value">~59<span class="metric-unit"> GtCO₂e</span></div>
        <div class="metric-label">Global GHG emissions (2019)</div>
        <div class="metric-detail">Fossil fuels &amp; land-use change</div>
      </div>
      <div class="metric-card cool-1">
        <div class="metric-value">~500<span class="metric-unit"> GtCO₂</span></div>
        <div class="metric-label">Remaining carbon budget</div>
