const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });

  const page = await browser.newPage();

  // Set viewport to match poster dimensions with high DPI
  await page.setViewport({
    width: 1200,
    height: 1697,
    deviceScaleFactor: 2
  });

  // Load the poster HTML
  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts and rendering to complete
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 2000));

  // Capture the full page as PNG
  await page.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    type: 'png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 1200, height: 1697 }
  });

  console.log('Poster rendered successfully!');
  await browser.close();
})().catch(err => {
  console.error('Rendering failed:', err);
  process.exit(1);
});

