  .risk-item.food { border-left-color: #f59e0b; }
  .risk-item.water { border-left-color: #06b6d4; }
  .risk-item.health { border-left-color: #ef4444; }

  .risk-icon {
    width: 32px;
    height: 32px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    flex-shrink: 0;
  }

  .risk-item.food .risk-icon { background: rgba(245,158,11,0.15); }
  .risk-item.water .risk-icon { background: rgba(6,182,212,0.15); }
  .risk-item.health .risk-icon { background: rgba(239,68,68,0.15); }

  .risk-content { flex: 1; }

  .risk-label {
    font-size: 12px;
    font-weight: 700;
    color: #e2e8f0;
    margin-bottom: 2px;
  }

  .risk-desc {
    font-size: 10px;
    color: #94a3b8;
    line-height: 1.4;
  }

  /* ── POPULATION CALLOUT ── */
  .population-callout {
    text-align: center;
    padding: 12px;
    background: linear-gradient(135deg, rgba(239,68,68,0.1), rgba(220,38,38,0.05));
    border: 1px solid rgba(239,68,68,0.15);
    border-radius: 8px;
    margin-bottom: 10px;
  }

  .population-callout .value {
    font-size: 24px;
    font-weight: 900;
    color: #f87171;
    line-height: 1.2;
  }

  .population-callout .label {
    font-size: 10px;
    color: #fca5a5;
    margin-top: 1px;
  }

  /* ── COMPARISON ── */
  .compare-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
  }

  .compare-col {
    padding: 14px;
    border-radius: 8px;
    border: 1px solid rgba(255,255,255,0.06);
  }

  .compare-col.cool {
    background: rgba(6,182,212,0.06);
    border-color: rgba(6,182,212,0.15);
  }

  .compare-col.warm {
    background: rgba(245,158,11,0.06);
    border-color: rgba(245,158,11,0.15);
  }

  .compare-col-title {
    font-size: 14px;
    font-weight: 800;
    margin-bottom: 10px;
    text-align: center;
  }

  .compare-col.cool .compare-col-title { color: #22d3ee; }
  .compare-col.warm .compare-col-title { color: #fbbf24; }

  .compare-item {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 6px 0;
    border-bottom: 1px solid rgba(255,255,255,0.04);
  }

  .compare-item:last-child { border-bottom: none; }

  .compare-item-label {
    font-size: 10px;
    color: #94a3b8;
  }

  .compare-item-value {
    font-size: 13px;
    font-weight: 700;
  }

  .compare-col.cool .compare-item-value { color: #22d3ee; }
  .compare-col.warm .compare-item-value { color: #fbbf24; }

  .compare-item-desc {
    font-size: 8.5px;
    color: #64748b;
    display: block;
    text-align: right;
  }

  /* ── URGENCY SECTION ── */
  .urgency-section {
    background: linear-gradient(135deg, rgba(220,38,38,0.08), rgba(245,158,11,0.06));
    border: 1px solid rgba(239,68,68,0.15);
    border-radius: 10px;
    padding: 24px 28px;
    display: flex;
    gap: 28px;
    align-items: center;
  }

  .urgency-left { flex: 1; }

  .urgency-left .section-title {
    color: #fbbf24;
    font-size: 18px;
  }

  .urgency-text {
    font-size: 11.5px;
    color: #cbd5e1;
    line-height: 1.55;
    margin-top: 8px;
  }

  .urgency-text strong {
    color: #fbbf24;
    font-weight: 700;
  }

  .urgency-right {
    width: 400px;
