      <div class="metric-card warm-3">
        <div class="metric-value">~59<span class="metric-unit"> GtCO₂e</span></div>
        <div class="metric-label">Global GHG emissions (2019)</div>
        <div class="metric-detail">Fossil fuels &amp; land-use change</div>
      </div>
      <div class="metric-card cool-1">
        <div class="metric-value">~500<span class="metric-unit"> GtCO₂</span></div>
        <div class="metric-label">Remaining carbon budget</div>
        <div class="metric-detail">50% chance of 1.5°C, from 2020</div>
      </div>
    </div>
    <div class="metrics-row-2">
      <div class="metric-card warm-4 large highlight">
        <div class="metric-value">43<span class="metric-unit">%</span></div>
        <div class="metric-label">Required GHG reduction by 2030</div>
        <div class="metric-detail">Below 2019 levels for 1.5°C pathway</div>
      </div>
      <div class="metric-card cool-2 large">
        <div class="metric-value">~0.20<span class="metric-unit"> m</span></div>
        <div class="metric-label">Sea level rise</div>
