const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  const context = await browser.newContext({
    deviceScaleFactor: 2,
    viewport: { width: 1200, height: 1697 }
  });

  const page = await context.newPage();

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for fonts
  await page.evaluate(() => document.fonts.ready);

  // Wait for infographic components to render (listen for poster-ready message)
  await page.waitForEvent('console', { timeout: 8000 }).catch(() => {});
  // Extra buffer for AntV rendering
  await page.waitForTimeout(3000);

  await page.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    type: 'png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 1200, height: 1697 }
  });

  console.log('Poster rendered successfully!');
  await browser.close();
})().catch(err => {
  console.error('Rendering failed:', err);
  process.exit(1);
});

